import React, { useState, useEffect } from "react";
import { supabase } from "./supabase.js";

const LOGO_URL = "data:image/png;base64,";
const HERO_BG_URL = "data:image/jpeg;base64,";

// =============================================================================
// UFOSTREET — plateforme d'inscription & classement
// =============================================================================

const ADMIN_PIN = "1970"; // ⚠️ change-le

const CATEGORIES = ["11-14 ans", "15-17 ans", "100% féminin"];
const EMPTY_PLAYER = { prenom: "", nom: "", age: "", sexe: "", tel: "", email: "", adresse: "" };
const STAGE_COLORS = ["#ff2e63", "#ff9f1c", "#3ddc84", "#4d9fff", "#b25cff", "#ff5cad", "#2ce8d6", "#ffd23f"];

// --- persistent shared storage (base de données Supabase) --------------------
// On stocke deux "documents" JSON dans une table `kv` : la clé "teams" et la
// clé "stages". Toute la logique de l'app reste identique.
const S = {
  async get(key, fb) {
    try {
      const { data, error } = await supabase.from("kv").select("value").eq("key", key).maybeSingle();
      if (error) throw error;
      return data ? data.value : fb;
    } catch (e) {
      console.error("Erreur de lecture:", e);
      return fb;
    }
  },
  async set(key, v) {
    try {
      const { error } = await supabase.from("kv").upsert({ key, value: v }, { onConflict: "key" });
      if (error) throw error;
    } catch (e) {
      console.error("Erreur d'enregistrement:", e);
    }
  },
};

const uid = () => Math.random().toString(36).slice(2, 8).toUpperCase();

// Une équipe est mixte si elle a au moins un H et au moins une F
function isMixte(team) {
  const sexes = (team.joueurs || []).map((j) => j.sexe);
  return sexes.includes("H") && sexes.includes("F");
}
const MIXTE_BONUS = 5; // points bonus par étape pour une équipe mixte

// Total des points d'une équipe.
// Le bonus mixte (+5) d'une étape ne compte QUE si l'équipe a réellement
// un score saisi (> 0) sur cette étape. Sans point saisi, total = 0.
function teamTotal(team) {
  const points = team.points || {};
  const bonus = team.mixteBonus || {};
  let total = 0;
  for (const [stageId, val] of Object.entries(points)) {
    const p = Number(val);
    if (!p) continue;            // pas de point réel sur cette étape → on ignore
    total += p;
    if (bonus[stageId]) total += MIXTE_BONUS;  // bonus seulement si l'étape a des points
  }
  return total;
}

function defaultStages() {
  return [
    { id: uid(), nom: "Étape 1", lieu: "", date: "", heure: "", categorie: "Toutes", couleur: "#ff2e63" },
    { id: uid(), nom: "Étape 2", lieu: "", date: "", heure: "", categorie: "Toutes", couleur: "#ff9f1c" },
  ];
}

// =============================================================================
export default function App() {
  const [tab, setTab] = useState("accueil");
  const [teams, setTeams] = useState([]);
  const [stages, setStages] = useState([]);
  const [loading, setLoading] = useState(true);
  const [isAdmin, setIsAdmin] = useState(false);
  const [activeTeam, setActiveTeam] = useState(null);

  useEffect(() => {
    let alive = true;
    (async () => {
      const t = await S.get("teams", []);
      let s = await S.get("stages", null);
      // Première utilisation : on crée les étapes par défaut dans la base.
      if (s === null) { s = defaultStages(); S.set("stages", s); }
      if (!alive) return;
      setTeams(t);
      setStages(s);
      setLoading(false);
    })();

    // Rafraîchit les données toutes les 15s pour que tous les appareils
    // voient les mêmes inscriptions et le même classement.
    const iv = setInterval(async () => {
      const t = await S.get("teams", []);
      const s = await S.get("stages", []);
      if (!alive) return;
      setTeams(t);
      setStages(s);
    }, 15000);

    return () => { alive = false; clearInterval(iv); };
  }, []);

  const saveTeams = (t) => { setTeams(t); S.set("teams", t); };
  const saveStages = (s) => { setStages(s); S.set("stages", s); };

  if (loading) return <Shell><div style={{ padding: 80, textAlign: "center", color: "#8a8a8a" }}>Chargement…</div></Shell>;

  return (
    <Shell tab={tab} setTab={setTab} isAdmin={isAdmin}>
      {tab === "accueil" && <Accueil setTab={setTab} />}
      {tab === "inscription" && <Inscription teams={teams} saveTeams={saveTeams} stages={stages} setTab={setTab} setActiveTeam={setActiveTeam} />}
      {tab === "equipe" && <EspaceEquipe teams={teams} saveTeams={saveTeams} stages={stages} activeTeam={activeTeam} setActiveTeam={setActiveTeam} />}
      {tab === "etapes" && <EtapesPublic stages={stages} />}
      {tab === "classement" && <Classement teams={teams} />}
      {tab === "admin" && <Admin teams={teams} saveTeams={saveTeams} stages={stages} saveStages={saveStages} isAdmin={isAdmin} setIsAdmin={setIsAdmin} />}
    </Shell>
  );
}

// =============================================================================
// LAYOUT
// =============================================================================
function Shell({ children, tab, setTab, isAdmin }) {
  const nav = [
    ["accueil", "Accueil"],
    ["inscription", "Inscription"],
    ["equipe", "Mon équipe"],
    ["etapes", "League"],
    ["classement", "Classement"],
    ["admin", "Admin"],
  ];
  return (
    <div style={{ minHeight: "100vh", background: "#0a0a0c", color: "#f2f2f2", fontFamily: "'Inter',system-ui,sans-serif" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Archivo+Black&family=Inter:wght@400;500;600;700;800&display=swap');
        * { box-sizing: border-box; }
        input, select { font-family: inherit; }
        .nav-item { cursor:pointer; padding:9px 15px; border-radius:999px; font-weight:700; font-size:14px; transition:all .15s; white-space:nowrap; }
        .ufo-btn:hover { filter:brightness(1.08); }
        @keyframes ufoIn { 0%{opacity:0; transform:translateY(30px) scale(.96)} 100%{opacity:1; transform:none} }
        @keyframes floaty { 0%,100%{transform:translateY(0)} 50%{transform:translateY(-14px)} }
        @keyframes beamGrow { 0%{opacity:0; transform:scaleY(0)} 100%{opacity:.5; transform:scaleY(1)} }
        @keyframes fadeUp { 0%{opacity:0; transform:translateY(18px)} 100%{opacity:1; transform:none} }
        @keyframes slowZoom { 0%{transform:scale(1.12)} 100%{transform:scale(1)} }
        @media (prefers-reduced-motion: reduce){ *{animation:none !important} }
      `}</style>

      <header style={{ borderBottom: "1px solid #1a1a1f", position: "sticky", top: 0, background: "#0a0a0ce6", backdropFilter: "blur(10px)", zIndex: 20 }}>
        <div style={{ maxWidth: 1080, margin: "0 auto", padding: "14px 20px", display: "flex", alignItems: "center", gap: 18, flexWrap: "wrap" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 10, cursor: "pointer" }} onClick={() => setTab && setTab("accueil")}>
            <img src={LOGO_URL} alt="UFO STREET LEAGUE" style={{ height: 34 }} />
          </div>
          {tab && (
            <nav style={{ display: "flex", gap: 4, marginLeft: "auto", flexWrap: "wrap" }}>
              {nav.map(([id, label]) => (
                <div key={id} className="nav-item" onClick={() => setTab(id)}
                  style={{ background: tab === id ? "#ff2e63" : "transparent", color: tab === id ? "#fff" : "#9a9aa4" }}>
                  {label}{id === "admin" && isAdmin ? " ✓" : ""}
                </div>
              ))}
            </nav>
          )}
        </div>
      </header>
      <main style={{ maxWidth: 1080, margin: "0 auto", padding: "30px 20px 90px" }}>{children}</main>
    </div>
  );
}

// =============================================================================
// ACCUEIL
// =============================================================================
